import unittest

from invoice import invoice_line
from labels import weight
from receipt import receipt_total


class TestFormats(unittest.TestCase):
    def test_an_invoice_line(self):
        self.assertEqual(invoice_line('Tea', 123456), 'Tea: $1,234.56')

    def test_a_receipt_total(self):
        self.assertEqual(receipt_total(5), 'TOTAL $0.05')

    def test_a_weight(self):
        self.assertEqual(weight(1500), '1.500 kg')
